{native.Advance(new(),600);var points=native.Movements.Where(m=>!m.Player).ToArray();Check(points.Length==6&&points[0].ToX>points[0].FromX&&points[1].ToX>points[1].FromX&&points[2].ToX<points[2].FromX,"Native signed budget advances full rightward steps then reverses after attempted segment completion");Check(points.All(p=>p.FromY==p.ToY)&&points[1].ToX==65.5,"Back-and-forth preserves exact horizontal motion for an exactly divisible segment");}
using(var native=new EncounterSession(adapter,Doc("new BackAndForth(1.3,distance:1)"),entity,7,new(Invulnerable:true))){native.Advance(new(),200);Check(Boss(native).X>65.5,"Non-divisible segment retains original full-step overshoot instead of endpoint clamping");}
