{native.Advance(new(),600);Check(native.Movements.Where(m=>!m.Player).All(m=>m.ToX<m.FromX),"Negative native budgets restart leftward segments without inventing alternation");}
var wall=NativeArena.Obstacles().First(o=>o.EnemyOccupySquare&&!o.Connects);
using(var native=new EncounterSession(adapter,Doc("new BackAndForth(1,distance:1)"),entity,7,new(Invulnerable:true),arena:new(){Tiles=[new(65,64,"Arena Dirt",wall.Id)]}))
{native.Advance(new(),400);var samples=native.Movements.Where(m=>!m.Player).ToArray();Check(samples.Any(m=>m.ToX<m.FromX),"Blocked rightward attempts still consume the segment budget and permit a later reversal");}
using(var native=new EncounterSession(adapter,Doc("new Protect(1,\"Big Yeti\",acquireRange:10,protectionRange:3,reprotectRange:1)"),entity,7,new(Invulnerable:true),arena:new(){Actors=[new(target,68.5,64.5)]}))
{native.Advance(new(),800);var host=Boss(native);var protectedActor=World(native).Enemies.Values.Single(e=>e.ObjectDesc.IdName==target);var arrived=host.X;native.Advance(new(),300);Check(Math.Abs(host.X-arrived)<1e-5&&Math.Abs(host.X-protectedActor.X)<=1,"Protect reaches the native arrival band and holds a completed state");protectedActor.Move(host.X+2,host.Y);native.Step(new());Check(host.X==arrived,"Protection distance preserves the larger restart band after arrival");protectedActor.Move(host.X+4,host.Y);native.Step(new());Check(host.X>arrived,"Protect restarts approach when the selected entity exceeds protectionRange");}
using(var native=new EncounterSession(adapter,Doc("new Protect(1,\"Cave Pirate Brawler\")"),entity,7,new(Invulnerable:true)))
{native.Advance(new(),300);Check(native.Movements.Where(m=>!m.Player).All(m=>m.ToX==m.FromX&&m.ToY==m.FromY),"Typed Protect query may select its matching host itself");}
using(var native=new EncounterSession(adapter,Doc("new Protect(1,\"Big Yeti\",acquireRange:4)"),entity,7,new(Invulnerable:true),arena:new(){Actors=[new(target,68.5,64.5)]}))
{native.Step(new());Check(Boss(native).X==64.5,"Protect acquisition uses strict native typed-target distance");}
using(var native=new EncounterSession(adapter,Doc("new PatrolCircle(4,1)"),entity,7,new(Invulnerable:true)))
{native.Step(new());Check(Boss(native).X>64.5&&Boss(native).Y>64.5,"Spawn patrol steers off-center toward its next clockwise circle point");var before=Boss(native).X;Boss(native).ApplyConditionEffect(ConditionEffectIndex.Paralyzed,300);native.Step(new());Check(Boss(native).X==before,"Native paralysis suspends patrol movement");}
using(var clockwise=new EncounterSession(adapter,Doc("new PatrolCircle(4,1,true)"),entity,7,new(Invulnerable:true)))
{clockwise.Step(new());var position=(Boss(clockwise).X,Boss(clockwise).Y);using var counter=new EncounterSession(adapter,Doc("new PatrolCircle(4,1,false)"),entity,7,new(Invulnerable:true));counter.Step(new());Check(Math.Abs(Boss(counter).X-position.X)<1e-5&&Math.Abs(Boss(counter).Y+position.Y-129)<1e-5,"Patrol direction retains mirrored native screen-space angle signs");}
var doc=Doc("new Protect(.3,\"Big Yeti\")");var node=doc.AllNodes.Single(n=>n.Kind=="Protect");Check(adapter.ReadCustomMovement(doc,node) is{Radius:2,Arrival:1,Acquire:10,Target:"Big Yeti"}&&adapter.EntityParameterFor(doc,node)?.Name=="protectee","Protected movement metadata separates acquisition, arrival and restart with actual XML input");var original=doc.Source;adapter.ApplyCustomMovement(doc,entity,node.Id,doc.Revision,new Dictionary<string,double>{{"reprotectRange",.75},{"protectionRange",2.5}});Check(doc.Undo()&&doc.Source==original&&doc.Redo()&&doc.Find(node.Id).Id==node.Id,"Native multi-bound edits preserve atomic source history and movement identity");doc.LockedNodes.Add(node.Id);Reject(()=>adapter.ApplyCustomMovement(doc,entity,node.Id,doc.Revision,new Dictionary<string,double>{{"acquireRange",5}}),"Custom movement handles respect native source locks");doc.LockedNodes.Clear();Reject(()=>adapter.ApplyCustomMovement(doc,entity,node.Id,doc.Revision-1,new Dictionary<string,double>{{"acquireRange",5}}),"Custom movement stale proposals reject atomically");Reject(()=>adapter.ApplyCustomMovement(doc,entity,node.Id,doc.Revision,new Dictionary<string,double>{{"acquireRange",double.MaxValue}}),"Protect distance edits respect actual float narrowing");
