var file=adapter.Catalog().Single(e=>e.Id==entity).SourceFile;var supplied=File.ReadAllText(file);string Source(string body)=>"using TKR.WorldServer.logic.behaviors;namespace TKR.WorldServer.logic{public partial class BehaviorDb{private _ StudioCustomMove=()=>Behav().Init(\""+entity+"\",new State(\"motion\","+body+"));}}";
foreach(var body in new[]{"new BackAndForth(.3,distance:2)","new PatrolCircle(4,.3)","new Protect(.3,\"Big Yeti\")"})
{var project=new StudioProject{SourceFile=file,Source=Source(body),EntityId=entity,Seed=7,Player=new(Invulnerable:true),Arena=new(){Actors=[new(target,68.5,64.5)]}};using var literal=new EncounterSession(adapter,Doc(body),entity,7,project.Player,arena:project.Arena);literal.Advance(new(),700);await using var compiled=await CompiledRuntime.StartAsync(adapter.ServerRoot,project);await compiled.AdvanceAsync(new(),700);Check(literal.Movements.Select(m=>(m.ActorId,m.FromX,m.FromY,m.ToX,m.ToY,m.Ms)).SequenceEqual(compiled.Movements.Select(m=>(m.ActorId,m.FromX,m.FromY,m.ToX,m.ToY,m.Ms))),"Literal and compiled "+body.Split('(')[0]+" retain complete native physical movement samples");}
Check(File.ReadAllText(file)==supplied,"Custom movement edits and native playback preserve supplied game source");Console.WriteLine($"{checks} native custom movement checks passed.");
